interface MountOptions<TTheme = Theme, TFactory = AdhocDomFactory> {
    /** DOM node the renderer draws into. The renderer owns the subtree. */
    container: HTMLElement;
    /** The panel to render (meridian.ui.v1.PanelDescriptor). */
    descriptor: PanelDescriptor;
    /** Host transport for the populate / action RPCs. */
    invoker: RpcInvoker;
    /**
     * Host policy for WHICH service/method this descriptor may dial through
     * {@link invoker}, and at which tier. The access-control peer of the other
     * host seams here: `renderIcon` / `resolveHref` / `renderGrammar` let the
     * host decide how a descriptor's intent is realised; `admission` lets it
     * decide whether that intent is permitted at all.
     *
     * This matters because a descriptor is data, and data now arrives from
     * places that are not the application author — meridian-mcp accepts a
     * model-authored ViewDescriptor and validates its SHAPE, not what it points
     * at, while a host's invoker may carry an authenticated session.
     *
     * OMITTED ⇒ reads (populate) are allowed and mutations (Action.call, form
     * submit, LRO start) are DENIED, with an error naming the entry to add.
     * Pass `"unrestricted"` to opt out explicitly. See ./admission.ts.
     */
    admission?: AdmissionPolicy;
    /**
     * Host transport for SERVER-STREAMING methods — what a StreamPanel subscribes
     * through. Optional and separate from {@link invoker} because streaming is a
     * surface CAPABILITY, not a given: a host that cannot stream simply omits it
     * and StreamPanel degrades down its ladder (a bounded snapshot, else the
     * placeholder). See stream.proto.
     */
    streamInvoker?: StreamInvoker;
    /** Active theme/skin (meridian.theme.v1). Each impl binds it natively. */
    theme?: TTheme;
    /** Runtime context (active resource path, identity, form values). */
    context?: RenderContext;
    /** Bespoke (AdhocPanel) handlers keyed by `handler_id`. */
    adhoc?: AdhocRegistry<TFactory>;
    /**
     * Host glyph resolver: maps an `icon` KEY (ChoiceOption.icon, Affordance.icon,
     * ConnectTarget.icon, CatalogItem.icon — brand-neutral keys the descriptor
     * carries, e.g. "github", "download") to a renderer-native glyph. The
     * "renderer draws, host wires" icon seam: the descriptor names the icon, the
     * host supplies the vector. Return type is renderer-specific (a ReactNode for
     * the React adapter, an HTMLElement for the web-components renderer), so it is
     * loosely typed here. Absent ⇒ renderers emit the key as a `data-icon`
     * attribute (never dropped) and draw no glyph.
     */
    renderIcon?: (key: string) => unknown;
    /**
     * Host route resolver — the LINK peer of the icon / grammar host seams, named
     * by `ColumnLink` (table.proto) which says the renderer "never builds a URL
     * itself: it hands the host the target kind + the cell's value (the entity's
     * id) and the host maps that to its own route".
     *
     * Meridian stays URL-agnostic; hosts own routes. Return a URL to draw the cell
     * as a link, or `null`/nothing to draw plain text — a renderer must never emit
     * a dead link. `targetKind` is empty for a self/detail link, in which case the
     * view's own `subject_kind` applies. `row` is the full source row, so a host
     * that needs more than the id (a tenant, a repo) can read it.
     */
    resolveHref?: (opts: {
        targetKind: string;
        id: string;
        row?: object;
    }) => string | null | undefined;
    /**
     * Host transcoder for a GrammarPanel — a declarative grammar (markdown /
     * mermaid / plantuml / graphviz / vega). This is the surface's capability set:
     * the host wires it ONLY for languages this surface can display, returning a
     * live result for those, or `null`/nothing for the rest → the renderer degrades
     * down the ladder (native markdown → `alt` → source text). Kits import no
     * grammar library.
     *
     * The return is a LIVE result, not just markup: a renderer-native node
     * (HTMLElement for web-components, ReactNode for React) that is already
     * interactive once mounted (vega-embed tooltips / zoom / brush "just work"), OR
     * a {@link GrammarHandle} whose `element`/`node` is mounted and whose optional
     * `dispose` frees the runtime, and whose `getSignal`/`onSignal` expose the
     * grammar's live selections to the FRAMEWORK — which resolves them the
     * meridian-idiomatic way (a `signal` FieldBinding source, rpc.proto) so an
     * interactive selection fires an RpcCall through the RpcInvoker like every
     * other panel action. A plain node return is equally valid. Loosely typed
     * (renderer-specific); `data` is the decoded google.protobuf.Struct.
     */
    renderGrammar?: (opts: {
        language: string;
        source: string;
        data?: unknown;
    }) => unknown;
}

interface PanelHandle {
    /** Re-render in place with a new descriptor (same container + transport). */
    update(descriptor: PanelDescriptor): void | Promise<void>;
    /** Tear the panel down and release listeners / resources. */
    unmount(): void;
}

interface RenderContext {
    currentResourcePath: string | null;
    uiIdentity: object | null;
    selectedRow: object | null;
    formValues: Record<string, unknown>;
}

interface RpcAdmission {
    /**
     * Methods reachable from a read callsite. OMITTED means "any", which is what
     * every host does today: populate already fires freely, so defaulting reads
     * closed would break every existing consumer on upgrade without closing the
     * hole this module exists for.
     */
    reads?: readonly string[];
    /**
     * Methods reachable from a mutation callsite. OMITTED means NONE — the
     * deliberate default, and the reason this module exists. A host that wants
     * actions to dial must say which ones.
     */
    mutations?: readonly string[];
    /**
     * Deny a read-tier call whose AIP verb says it mutates (Create / Update /
     * Patch / Delete), even when `reads` would otherwise admit it. Defaults to
     * TRUE: this is a tripwire, never a grant — it can only ever refuse, and it
     * refuses exactly the shape that matters, a destructive call smuggled into a
     * populate slot where it auto-fires on mount with no user gesture.
     */
    inferFromAipVerbs?: boolean;
    /** Called on every refusal. A host should log this; the dev overlay shows it. */
    onDenied?(denial: AdmissionDenial): void;
}

interface RpcInvoker {
    invoke(service: string, method: string, request: object): Promise<object>;
}

interface StatComputed {
    /** The formatted value + unit suffix (e.g. "1,234 employees", "87.5%"). */
    formattedValue: string;
    /** Computed (or overridden) trend direction; "none" when there is no delta. */
    trend: StatTrend;
    /** Formatted signed delta (e.g. "+30", "-5.0%"), or null when there is none. */
